def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n < 3:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_opp = op[-1]

    oppD_total = sum(1 for x in op if x == 'D')
    oppC_total = n - oppD_total
    myD_total = sum(1 for x in my if x == 'D')

    oppD_last5 = sum(1 for x in op[-5:] if x == 'D')
    oppD_last10 = sum(1 for x in op[-10:] if x == 'D')
    oppC_last10 = sum(1 for x in op[-10:] if x == 'C')

    d_streak = 0
    for x in reversed(op):
        if x == 'D':
            d_streak += 1
        else:
            break

    dd_streak = 0
    for i in reversed(range(n)):
        if my[i] == 'D' and op[i] == 'D':
            dd_streak += 1
        else:
            break

    unprovoked = 0
    for i in range(n):
        if op[i] == 'D' and (i == 0 or my[i - 1] == 'C'):
            unprovoked += 1

    retal = 0
    nonretal = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            if op[i] == 'D':
                retal += 1
            else:
                nonretal += 1

    likely_AD = n >= 12 and oppC_total == 0 and oppD_total == n

    if likely_AD:
        return 'D'

    if n >= 90 and oppD_total * 4 >= n * 3 and oppC_last10 == 0 and oppC_total <= 10:
        return 'D'

    friendly_exploitable = retal == 0 and nonretal >= 1 and oppD_last5 <= 2
    exploitable = friendly_exploitable or (oppD_total == 0 and n >= 85)

    if exploitable and n >= 25:
        return 'D'

    if n >= 96:
        return 'C'

    if last_opp == 'D':
        if last_my == 'D':
            if oppC_total == 0:
                if n <= 6 and d_streak >= 5:
                    return 'C'
            elif d_streak >= 5:
                return 'C'

            if dd_streak >= 2 and oppC_total > 0:
                return 'C'
            if d_streak >= 3 and oppC_total > 0 and oppD_total * 5 < n * 3:
                return 'C'

            return 'D'
        else:
            if n >= 2 and my[-2] == 'D':
                if oppC_total > 0 and oppD_total * 3 < n * 2:
                    return 'C'
                if oppC_total == 0 and d_streak <= 6 and n <= 7:
                    return 'C'

            if unprovoked <= 1 and oppC_total >= 8 and oppD_last10 <= 1:
                return 'C'
            if d_streak >= 3 and oppC_total > 0 and oppD_total * 5 < n * 3:
                return 'C'
            if oppD_total * 3 >= n:
                return 'D'
            if unprovoked >= 2:
                return 'D'

            return 'D'

    if last_my == 'D':
        return 'C'

    if oppD_total == 0:
        if myD_total == 0 and n == 40:
            return 'D'
        if n >= 85:
            return 'D'

    if (
        oppD_total <= 1
        and oppD_last10 == 0
        and myD_total == 0
        and n >= 55
        and rng.random() < 0.1
    ):
        return 'D'

    return 'C'
